import json,re
async def s(q,kw=None,n=5,w=250):
    r=json.loads(await web_search({"query":q}))
    print("##",q)
    for x in r[:n]:
        c=x['content']
        print("-",x['title'],x['url'])
        if kw:
            for k in kw:
                for m in list(re.finditer(k,c))[:2]:
                    print("   ",c[max(0,m.start()-50):m.start()+w].replace("\n"," "))
        else: print("  ",c[:w].replace("\n"," "))
await s("Apple 10-K FY2025 net sales net income operating income depreciation and amortization",["Net sales","Net income","Depreciation and amortization","Operating income"],3,150)
